replace:
nounRow(input, applicability, ports) === 'P' && applicability.witness !== null
  ? 'W'
  : nounRow(input, applicability, ports);

find:
if (row === 'A0' || row === 'N0')
  throw new Error(
    `J-1: slot 11 owes a fresh read on row ${row} and no noun port is bound; the pipeline was assembled without Gate 11's capability owner`,
  );

edits.replace:
  readonly producedByIntentTokenHash: string | null;
  readonly bodyHash: string;
}
